              var nE = no.GetMass();
              var nR = this.copterBody.GetLocalPoint(ni);
              var nW = new q3.RM(nR.x - this.bladeLocalCenter.x, nR.y - this.bladeLocalCenter.y);
              nW.Normalize();
              nW.MulM(this.copterBody.m_xf.R);
