            var nl = Math.cos(nu) * this.ejectImpulse;
            var no = Math.sin(nu) * this.ejectImpulse;
            this.chestBody.ApplyImpulse(new q3.RM(nl, no), this.chestBody.GetWorldCenter());
            this.pelvisBody.ApplyImpulse(new q3.RM(nl, no), this.pelvisBody.GetWorldCenter());
