          var nB = this._session.contactListener;
          nB.deleteListener(q4.fI.RESULT, this.backShape);
          nB.deleteListener(q4.fI.RESULT, this.baseShape);
          nB.deleteListener(q4.fI.RESULT, this.wheel1Shape);
          nB.deleteListener(q4.fI.RESULT, this.wheel2Shape);
          nB.deleteListener(q4.fI.ADD, this.backShape);
          nB.deleteListener(q4.fI.ADD, this.baseShape);
          nB.deleteListener(q4.fI.ADD, this.wheel1Shape);
          nB.deleteListener(q4.fI.ADD, this.wheel2Shape);
          this.copterSmashed = true;
          if (!this.bladeSmashed) {
            this.bladeSmash(nt);
          }
          if (this.copterFrontMC.inner.leg1.visible == 1) {
            this.copterLegSmash(this.wheel1Shape, nt, false);
          }
          if (this.copterFrontMC.inner.leg2.visible == 1) {
            this.copterLegSmash(this.wheel2Shape, nt, false);
          }
