            if (this.mowerHand1) {
              nt.DestroyJoint(this.mowerHand1);
              this.mowerHand1 = null;
            }
            if (this.mowerHand2) {
              nt.DestroyJoint(this.mowerHand2);
              this.mowerHand2 = null;
            }
            if (this.mowerFoot1) {
              nt.DestroyJoint(this.mowerFoot1);
              this.mowerFoot1 = null;
            }
            if (this.mowerFoot2) {
              nt.DestroyJoint(this.mowerFoot2);
              this.mowerFoot2 = null;
            }
            var nB = this.upperLeg1Body.GetShapeList();
            nB.m_isSensor = false;
            nt.Refilter(nB);
            (nB = this.upperLeg2Body.GetShapeList()).m_isSensor = false;
            nt.Refilter(nB);
            this.lowerLeg1Shape.m_isSensor = false;
            nt.Refilter(this.lowerLeg1Shape);
            this.lowerLeg2Shape.m_isSensor = false;
            nt.Refilter(this.lowerLeg2Shape);
            this.frontShockJoint.EnableMotor(false);
            this.frontShockJoint.SetLimits(0, 0);
            this.frontShockJoint.SetMotorSpeed(0);
            this.backShockJoint.EnableMotor(false);
            this.backShockJoint.SetLimits(0, 0);
            this.backShockJoint.SetMotorSpeed(0);
